char* longestPalindrome(char* s) {
    if (!s || s[0] == '\0') {
        char* empty = (char*)malloc(1);
        empty[0] = '\0';
        return empty;
    }
    int n = strlen(s);
    int start = 0, maxLen = 1;

    for (int i = 0; i < n; i++) {
        // Odd-length palindrome
        int l = i, r = i;
        while (l >= 0 && r < n && s[l] == s[r]) {
            l--;
            r++;
        }
        int curLen = (r - 1) - (l + 1) + 1;
        if (curLen > maxLen) {
            start = l + 1;
            maxLen = curLen;
        }

        // Even-length palindrome
        l = i;
        r = i + 1;
        while (l >= 0 && r < n && s[l] == s[r]) {
            l--;
            r++;
        }
        curLen = (r - 1) - (l + 1) + 1;
        if (curLen > maxLen) {
            start = l + 1;
            maxLen = curLen;
        }
    }

    char* res = (char*)malloc(maxLen + 1);
    strncpy(res, s + start, maxLen);
    res[maxLen] = '\0';
    return res;
}

