class Solution {
public:
    string longestPalindrome(string s) {
        if (s.empty()) return "";
        int start = 0, maxLen = 1;
        int n = s.length();

        auto expand = [&](int l, int r) {
            while (l >= 0 && r < n && s[l] == s[r]) {
                l--;
                r++;
            }
            return make_pair(l + 1, r - 1);
        };

        for (int i = 0; i < n; i++) {
            auto r1 = expand(i, i);
            if (r1.second - r1.first + 1 > maxLen) {
                start = r1.first;
                maxLen = r1.second - r1.first + 1;
            }
            auto r2 = expand(i, i + 1);
            if (r2.second - r2.first + 1 > maxLen) {
                start = r2.first;
                maxLen = r2.second - r2.first + 1;
            }
        }
        return s.substr(start, maxLen);
    }
};

