class Solution:
    def longestPalindrome(self, s: str) -> str:
        if not s: return ""
        start, max_l = 0, 1
        def expand(l, r):
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1
                r += 1
            return l + 1, r - 1
        for i in range(len(s)):
            l1, r1 = expand(i, i)
            if r1 - l1 + 1 > max_l:
                start, max_l = l1, r1 - l1 + 1
            l2, r2 = expand(i, i + 1)
            if r2 - l2 + 1 > max_l:
                start, max_l = l2, r2 - l2 + 1
        return s[start:start+max_l]

