    if (!p) return NULL;
    ++p;

    size_t cap = 256, len = 0;
    char* out = (char*)malloc(cap);
    if (!out) return NULL;

    while (*p) {
        unsigned char c = (unsigned char)*p++;
        if (c == '"') {
            out[len] = '\0';
            return out;
        }
        if (c == '\\') {
            char e = *p++;
            switch (e) {
                case '"': c = '"'; break;
                case '\\': c = '\\'; break;
                case '/': c = '/'; break;
                case 'b': c = '\b'; break;
                case 'f': c = '\f'; break;
                case 'n': c = '\n'; break;
                case 'r': c = '\r'; break;
                case 't': c = '\t'; break;
                default: free(out); return NULL;
            }
        }
        if (len + 1 >= cap) {
            cap *= 2;
            char* tmp = (char*)realloc(out, cap);
            if (!tmp) { free(out); return NULL; }
            out = tmp;
        }
        out[len++] = (char)c;
    }

    free(out);
    return NULL;
}

